"""DANFSe generated by the site from the AUTHORIZED NFS-e XML (the one returned by Sefin Nacional and checked by the site).

There is no contributor API for the official DANFSe today (ADN restricted: /danfse -> 404; production docs: 503; the
official manuals of ADN and Emissor Público do not describe one). This PDF is a graphic representation built only from
the authorized XML; it never invents values and says so on the page.
"""
from datetime import datetime
from decimal import Decimal, InvalidOperation
from fpdf import FPDF
from lxml import etree

NS = {'n': 'http://www.sped.fazenda.gov.br/nfse'}
TRIB_ISSQN = {'1': 'Operação tributável', '2': 'Imunidade', '3': 'Exportação de serviço', '4': 'Não incidência'}
RET_ISSQN = {'1': 'Não retido', '2': 'Retido pelo tomador', '3': 'Retido pelo intermediário'}
SIMPLES = {'1': 'Não optante', '2': 'Optante — MEI', '3': 'Optante — ME/EPP'}
GREEN = (22, 91, 69)


def _latin1(text) -> str:
    # Core PDF fonts are Latin-1; replace typographic characters instead of failing.
    table = str.maketrans({'—': '-', '–': '-', '“': '"', '”': '"', '‘': "'", '’': "'", '…': '...', '•': '-', ' ': ' '})
    return str(text or '').translate(table).encode('latin-1', 'replace').decode('latin-1')


def _doc(value: str) -> str:
    d = ''.join(ch for ch in str(value or '') if ch.isdigit())
    if len(d) == 14:
        return f'{d[:2]}.{d[2:5]}.{d[5:8]}/{d[8:12]}-{d[12:]}'
    if len(d) == 11:
        return f'{d[:3]}.{d[3:6]}.{d[6:9]}-{d[9:]}'
    return d


def _money(value: str) -> str:
    try:
        n = Decimal(str(value))
    except (InvalidOperation, ValueError):
        return '-'
    s = f'{n:,.2f}'.replace(',', 'X').replace('.', ',').replace('X', '.')
    return 'R$ ' + s


def _date(value: str, with_time=True) -> str:
    try:
        dt = datetime.fromisoformat(str(value))
    except ValueError:
        return str(value or '-')
    return dt.strftime('%d/%m/%Y %H:%M:%S' if with_time else '%d/%m/%Y')


def _key(key: str) -> str:
    return ' '.join(key[i:i + 4] for i in range(0, len(key), 4))


def _address(node) -> str:
    if node is None:
        return ''
    get = lambda p: node.findtext(p, namespaces=NS) or ''
    parts = [get('n:xLgr'), get('n:nro'), get('n:xCpl'), get('n:xBairro')]
    nac = node.find('n:endNac', NS)
    city = get('n:cMun') or (nac.findtext('n:cMun', namespaces=NS) if nac is not None else '')
    cep = get('n:CEP') or (nac.findtext('n:CEP', namespaces=NS) if nac is not None else '')
    uf = get('n:UF')
    text = ', '.join(p for p in parts if p)
    tail = ' - '.join(p for p in [f'IBGE {city}' if city else '', uf, f'CEP {cep[:5]}-{cep[5:]}' if len(cep) == 8 else ''] if p)
    return ' | '.join(p for p in [text, tail] if p)


class _Pdf(FPDF):
    test_env = False

    def header(self):
        if self.test_env:
            with self.local_context(text_color=(225, 225, 225)):
                self.set_font('Helvetica', 'B', 46)
                with self.rotation(35, x=105, y=160):
                    self.text(18, 175, 'SEM VALOR FISCAL')

    def footer(self):
        self.set_y(-14)
        self.set_font('Helvetica', '', 7)
        self.set_text_color(90, 90, 90)
        self.multi_cell(0, 3.4, _latin1('Representação gráfica gerada pelo sistema Tríade a partir do XML da NFS-e autorizada pela Sefin Nacional. '
                                        'Confira a autenticidade pela chave de acesso no Portal Nacional da NFS-e. Página ') + str(self.page_no()), align='C')


def build_danfse(nfse_xml: str) -> bytes:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    root = etree.fromstring(nfse_xml.encode('utf-8'), parser)
    inf = root.find('n:infNFSe', NS)
    dps = root.find('n:infNFSe/n:DPS/n:infDPS', NS)
    if inf is None or dps is None:
        raise ValueError('XML da NFS-e sem infNFSe/infDPS.')
    t = lambda node, path: (node.findtext(path, namespaces=NS) or '').strip() if node is not None else ''
    key = (inf.get('Id') or '')[3:]
    test_env = t(dps, 'n:tpAmb') == '2'

    pdf = _Pdf(format='A4')
    pdf.test_env = test_env
    pdf.set_auto_page_break(True, margin=18)
    pdf.set_margins(12, 12, 12)
    pdf.add_page()
    width = pdf.w - 24

    def section(title):
        pdf.ln(2)
        pdf.set_fill_color(*GREEN); pdf.set_text_color(255, 255, 255); pdf.set_font('Helvetica', 'B', 9)
        pdf.cell(width, 6, _latin1('  ' + title.upper()), fill=True, new_x='LMARGIN', new_y='NEXT')
        pdf.set_text_color(20, 20, 20)

    def field(label, value, w=None, last=False):
        w = w or width
        x, y = pdf.get_x(), pdf.get_y()
        pdf.set_font('Helvetica', '', 6.5); pdf.set_text_color(90, 90, 90)
        pdf.cell(w, 3.6, _latin1(label.upper()))
        pdf.set_xy(x, y + 3.6)
        pdf.set_font('Helvetica', 'B' if value else '', 9); pdf.set_text_color(20, 20, 20)
        pdf.multi_cell(w, 4.6, _latin1(value or '-'), new_x='RIGHT' if not last else 'LMARGIN', new_y='TOP' if not last else 'NEXT')
        if not last:
            pdf.set_xy(x + w, y)

    def row(*items):
        y = pdf.get_y(); bottoms = []
        x = pdf.l_margin
        for i, (label, value, frac) in enumerate(items):
            pdf.set_xy(x, y)
            field(label, value, width * frac, last=True)
            bottoms.append(pdf.get_y()); x += width * frac
        pdf.set_y(max(bottoms) + 1)

    # Title block
    pdf.set_font('Helvetica', 'B', 13); pdf.set_text_color(*GREEN)
    pdf.cell(width * 0.62, 7, _latin1('DANFSe'), new_x='RIGHT', new_y='TOP')
    pdf.set_font('Helvetica', 'B', 12); pdf.set_text_color(20, 20, 20)
    pdf.cell(width * 0.38, 7, _latin1('NFS-e nº ' + t(inf, 'n:nNFSe')), align='R', new_x='LMARGIN', new_y='NEXT')
    pdf.set_font('Helvetica', '', 8.5); pdf.set_text_color(60, 60, 60)
    pdf.cell(width, 4.5, _latin1('Documento Auxiliar da Nota Fiscal de Serviço eletrônica — Padrão Nacional'), new_x='LMARGIN', new_y='NEXT')
    if test_env:
        pdf.ln(1.5)
        pdf.set_fill_color(180, 35, 24); pdf.set_text_color(255, 255, 255); pdf.set_font('Helvetica', 'B', 9)
        pdf.cell(width, 6.5, _latin1('PRODUÇÃO RESTRITA (AMBIENTE DE TESTES) — DOCUMENTO SEM VALOR FISCAL'), align='C', fill=True, new_x='LMARGIN', new_y='NEXT')
        pdf.set_text_color(20, 20, 20)
    pdf.ln(2)
    row(('Chave de acesso', _key(key), 1.0))
    status = 'Autorizada' if t(inf, 'n:cStat') == '100' else ('Código ' + t(inf, 'n:cStat'))
    row(('Competência', _date(t(dps, 'n:dCompet'), False), 0.2), ('Emissão da DPS', _date(t(dps, 'n:dhEmi')), 0.27),
        ('Autorização (processamento)', _date(t(inf, 'n:dhProc')), 0.3), ('Situação', status, 0.23))
    row(('DPS série / número', f"{t(dps, 'n:serie')} / {t(dps, 'n:nDPS')}", 0.2), ('Município emissor', t(inf, 'n:xLocEmi'), 0.4),
        ('Nº do DF-e (nDFSe)', t(inf, 'n:nDFSe'), 0.4))

    section('Prestador do serviço (emitente)')
    emit = inf.find('n:emit', NS); prest = dps.find('n:prest', NS)
    row(('CNPJ / CPF', _doc(t(emit, 'n:CNPJ') or t(emit, 'n:CPF')), 0.3), ('Nome / razão social', t(emit, 'n:xNome'), 0.7))
    row(('Endereço', _address(emit.find('n:enderNac', NS) if emit is not None else None), 0.7),
        ('Simples Nacional', SIMPLES.get(t(prest, 'n:regTrib/n:opSimpNac'), '-'), 0.3))

    section('Tomador do serviço')
    toma = dps.find('n:toma', NS)
    row(('CNPJ / CPF', _doc(t(toma, 'n:CNPJ') or t(toma, 'n:CPF')) or '-', 0.3), ('Nome / razão social', t(toma, 'n:xNome') or 'Não identificado', 0.7))
    if toma is not None and toma.find('n:end', NS) is not None:
        row(('Endereço', _address(toma.find('n:end', NS)), 1.0))

    section('Serviço prestado')
    serv = dps.find('n:serv', NS)
    row(('Código de tributação nacional', f"{t(serv, 'n:cServ/n:cTribNac')} — {t(inf, 'n:xTribNac')}", 1.0))
    nbs = t(serv, 'n:cServ/n:cNBS')
    if nbs:
        fmt = f'{nbs[0]}.{nbs[1:5]}.{nbs[5:7]}.{nbs[7:9]}' if len(nbs) == 9 else nbs
        row(('NBS', f"{fmt} — {t(inf, 'n:xNBS')}", 1.0))
    row(('Local da prestação', t(inf, 'n:xLocPrestacao') or t(serv, 'n:locPrest/n:cLocPrestacao'), 0.5),
        ('Município de incidência do ISSQN', t(inf, 'n:xLocIncid') or '-', 0.5))
    row(('Descrição do serviço', t(serv, 'n:cServ/n:xDescServ'), 1.0))

    section('Valores e tributação')
    vals = dps.find('n:valores', NS)
    trib = vals.find('n:trib/n:tribMun', NS) if vals is not None else None
    aliq = t(trib, 'n:pAliq')
    tot = vals.find('n:trib/n:totTrib', NS) if vals is not None else None
    if t(tot, 'n:pTotTribSN'):
        total = f"{t(tot, 'n:pTotTribSN').replace('.', ',')}% (Simples Nacional, aproximado)"
    elif t(tot, 'n:indTotTrib'):
        total = 'Não informado'
    else:
        total = '-'
    row(('Valor do serviço', _money(t(vals, 'n:vServPrest/n:vServ')), 0.25), ('Tributação do ISSQN', TRIB_ISSQN.get(t(trib, 'n:tribISSQN'), '-'), 0.25),
        ('Retenção do ISSQN', RET_ISSQN.get(t(trib, 'n:tpRetISSQN'), '-'), 0.25), ('Alíquota ISSQN', (aliq.replace('.', ',') + '%') if aliq else 'Não informada', 0.25))
    row(('Tributos aproximados (Lei 12.741/2012)', total, 0.5), ('Valor líquido da NFS-e', _money(t(inf, 'n:valores/n:vLiq')), 0.5))

    obs = t(serv, 'n:infoCompl/n:xInfComp')
    if obs:
        section('Informações complementares')
        row(('Observações', obs, 1.0))

    return bytes(pdf.output())
